        jdbc.update("ALTER SEQUENCE seq_case_no RESTART WITH 1");
        jdbc.update("ALTER SEQUENCE seq_doc_no RESTART WITH 1");
        mutableClock.setInstant(TestClockConfig.START);
    }
}

