```java
@Service
public class OffsiteEnforcementService {

    static final Duration DEDUP_WINDOW = Duration.ofMinutes(5);

    // evidence status constants
    public static final String STATUS_COMPLETE = "COMPLETE";
    public static final String STATUS_MANUAL_PENDING = "MANUAL_PENDING";
    public static final String STATUS_DUPLICATE = "DUPLICATE";
    public static final String STATUS_LATE = "LATE";

    // missing item codes
    public static final String MISSING_IMAGE_REF = "IMAGE_REF";
    public static final String MISSING_DEVICE_STATUS = "DEVICE_STATUS";
    public static final String MISSING_CALIBRATION = "CALIBRATION_EXPIRED";

    deps: ReferenceRepository, WeighDeviceRepository, OffsiteWeighRecordRepository,
          OffsiteLateEventRepository, WeighRecordRepository, CaseRepository,
          DecisionRepository, EnforcementService, Clock

    @Transactional
    public OffsiteWeighResponse ingest(OffsiteWeighRequest req) {
        Instant now = Instant.now(clock);
        String fingerprint = Fingerprints.of("OFFSITE", req.requestId(), req.plateNo(), req.laneCode(),
                req.deviceCode(), req.weighTime().toString(),
                req.totalKg().stripTrailingZeros().toPlainString(),
                req.imageRef() == null ? "" : req.imageRef());

        OffsiteWeighRecordRow existing = offsiteRepository.findByRequestId(req.requestId());
        if (existing != null) {
            if (!existing.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("IDEMPOTENT_PARAM_CONFLICT", ...);
            }
            return toResponse(existing, true);
        }

        VehicleRow vehicle = referenceRepository.findVehicle(req.plateNo());
        if (vehicle == null) throw notFound;
        BigDecimal limitKg = referenceRepository.findLimitKg(vehicle.axleType());
        if (limitKg == null) throw unprocessable AXLE_LIMIT_MISSING;
        BigDecimal rate = OverloadRules.overloadRate(req.totalKg(), limitKg);
        DecisionTier tier = OverloadRules.tierOf(rate);

        WeighDeviceRow device = weighDeviceRepository.findByDeviceCode(req.deviceCode());

        Instant from = req.weighTime().minus(DEDUP_WINDOW);
        Instant to = req.weighTime().plus(DEDUP_WINDOW);

        // 结案后迟到：窗口内同车牌同检测站案件已结案 -> 只记迟到事件
        if (device != null) {
            CaseRow closedCase = caseRepository.findByPlateStationWithinWindow(
                    req.plateNo(), device.stationCode(), from, to).stream()
                    .filter(c -> CaseStatus.CLOSED.name().equals(c.status()))
                    .findFirst().orElse(null);
            if (closedCase != null) {
                long id = insertRecord(req, fingerprint, vehicle, limitKg, rate, tier,
                        STATUS_LATE, "", null, null, closedCase.id(), null, now);
                lateEventRepository.insert(id, closedCase.id(), ..., "案件 "+closedCase.caseNo()+" 已结案，迟到非现场数据只记迟到事件，不改已结案件", now);
                return toResponse(offsiteRepository.findById(id), false);
            }
        }

        // 证据链三项：称重数据（已校验）、合成影像标识、设备状态记录（含校准有效期）
        List<String> missing = new ArrayList<>();
        if (req.imageRef() == null || req.imageRef().isBlank()) missing.add(MISSING_IMAGE_REF);
        if (device == null || !"NORMAL".equals(device.status())) {
            missing.add(MISSING_DEVICE_STATUS);
        } else if (req.weighTime().isBefore(device.calibrationValidFrom())
                || req.weighTime().isAfter(device.calibrationValidUntil())) {
            missing.add(MISSING_CALIBRATION);
        }
        if (!missing.isEmpty()) {
            long id = insertRecord(... STATUS_MANUAL_PENDING, String.join(",", missing), ...);
            return toResponse(findById(id), false);
        }

        // 窗口去重：现场记录优先，再非现场锚点；窗口内只保留首次
        WeighRecordRow onsite = weighRecordRepository.findByPlateWithinWindow(req.plateNo(), from, to);
        if (onsite != null) {
            long id = insertRecord(... STATUS_DUPLICATE, "", "ONSITE", onsite.id(), null, null, now);
            return toResponse(...);
        }
        OffsiteWeighRecordRow anchor = offsiteRepository.findRetainedByPlateWithinWindow(req.plateNo(), from, to);
        if (anchor != null) {
            long id = insertRecord(... STATUS_DUPLICATE, "", "OFFSITE", anchor.id(), ...);
            return toResponse(...);
        }

        // 证据链齐全：立案（或复用未结案件）、入过磅记录、自动生成处罚决定
        CaseRow caseRow = caseRepository.findByBizKey(req.plateNo(), device.stationCode(), req.weighTime());
        if (caseRow == null) {
            caseRow = enforcementService.createCase(req.plateNo(), device.stationCode(), req.weighTime(), now);
        }
        String role = enforcementService.resolveLiveRole(req.plateNo(), device.stationCode(), req.weighTime(), WeighMode.DYNAMIC);
        WeighRecordRow weighRow = new WeighRecordRow(null, "OSW-" + req.requestId(),
                Fingerprints.of("OFFSITE_WEIGH", req.requestId()), req.plateNo(), device.stationCode(),
                req.weighTime(), WeighMode.DYNAMIC.name(), req.totalKg(), vehicle.axleType(),
                limitKg, rate, tier.name(), role, caseRow.id(), now);
        long weighRecordId;
        try {
            weighRecordId = weighRecordRepository.insert(weighRow);
        } catch (DuplicateKeyException e) {
            // 并发下现场同键记录已写入：转为窗口去重，只保留首次
            WeighRecordRow raced = weighRecordRepository.findByDedupKey(...);
            long id = insertRecord(... STATUS_DUPLICATE, "", "ONSITE", raced == null ? null : raced.id(), ...);
            return toResponse(...);
        }
        WeighRecordRow authoritative = weighRecordRepository.findAuthoritative(req.plateNo(), device.stationCode(), req.weighTime());
        Long decisionId = null;
        if (authoritative != null && authoritative.id() == weighRecordId) {
            String autoRequestId = "AUTO-" + req.requestId();
            decisionId = enforcementService.createDecisionForCase(caseRow, authoritative, req.plateNo(),
                    autoRequestId, Fingerprints.of("DECISION", autoRequestId, req.plateNo(),
                    device.stationCode(), req.weighTime().toString()), now);
        }
        long id = insertRecord(req, fingerprint, ..., STATUS_COMPLETE, "", null, null, caseRow.id(), decisionId, now);
        return toResponse(offsiteRepository.findById(id), false);
    }
