        var docs = decisionRepository.findByCaseId(caseRow.id());
        assertThat(docs).hasSize(1);
        assertThat(docs.get(0).status()).isEqualTo("ACTIVE");
        assertThat(ledgerRepository.sumPointsByCase(caseRow.id())).isEqualTo(3);
